#!/bin/zsh
# Only the library (out/libmotolii.dylib), not the shells and checks edit.sh also builds: for a change in motolii.mm.
# Then restart the window (a native library cannot be hot reloaded).   ./build_lib.sh
cd "$(dirname "$0")"
KIT_EXTRA="-dynamiclib -install_name @rpath/libmotolii.dylib $(pkg-config --cflags --libs gstreamer-1.0 gstreamer-app-1.0 gstreamer-video-1.0) -lgltfio -lgltfio_core -ldracodec -DSQLITE_ENABLE_SESSION -DSQLITE_ENABLE_PREUPDATE_HOOK -I/opt/homebrew/opt/sqlite/include /opt/homebrew/opt/sqlite/lib/libsqlite3.dylib $PWD/physics.cpp $PWD/script.cpp -I$PWD/third_party/thermion_frame/include $PWD/third_party/thermion_frame/FrameScheduler.cpp -framework CoreVideo $PWD/splatfx.cpp $PWD/three_isf.cpp $PWD/midi_roll.cpp -lmatp $PWD/out/isf.o -I/opt/homebrew/opt/quickjs-ng/include -L/opt/homebrew/opt/quickjs-ng/lib -lqjs -Wl,-rpath,/opt/homebrew/opt/quickjs-ng/lib -I$PWD/third_party/physics/JoltPhysics -DJPH_CROSS_PLATFORM_DETERMINISTIC -DJPH_DEBUG_RENDERER -DJPH_OBJECT_LAYER_BITS=16 -DJPH_OBJECT_STREAM -DJPH_PROFILE_ENABLED -ffp-contract=off $PWD/third_party/physics/JoltPhysics/jbuild/libJolt.a" BUILDONLY=1 ./dawn_probe/kit_wgpu.sh motolii
mv out/motolii_wgpu out/libmotolii.dylib
